"""Self-contained Kaggle entry point for v1-beta checkpoint evaluation."""

import base64
import io
import json
import subprocess
import sys
import tarfile
import traceback
from pathlib import Path


EMBEDDED_KRONOS_ARCHIVE_B64 = """

"""


class Tee:
    def __init__(self, *streams):
        self.streams = streams

    def write(self, value):
        for stream in self.streams:
            stream.write(value)
            stream.flush()

    def flush(self):
        for stream in self.streams:
            stream.flush()


def extract_source():
    source_root = Path("/kaggle/working/Kronos")
    if not source_root.is_dir():
        archive = base64.b64decode(EMBEDDED_KRONOS_ARCHIVE_B64)
        if not archive:
            raise RuntimeError("Embedded Kronos source archive is empty")
        with tarfile.open(fileobj=io.BytesIO(archive), mode="r:gz") as bundle:
            bundle.extractall(source_root.parent)
    return source_root


def main():
    output = Path("/kaggle/working/kronos_v1_beta_checkpoint_evaluation")
    output.mkdir(parents=True, exist_ok=True)
    log_handle = (output / "run.log").open("a", buffering=1)
    sys.stdout = Tee(sys.__stdout__, log_handle)
    sys.stderr = Tee(sys.__stderr__, log_handle)
    try:
        source_root = extract_source()
        sys.path.insert(0, str(source_root))
        gpu_name = subprocess.run(
            ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"],
            capture_output=True,
            text=True,
            check=False,
        ).stdout.strip()
        if "P100" not in gpu_name:
            raise RuntimeError(f"Formal checkpoint evaluation requires P100, got {gpu_name}")
        arch_check = subprocess.run(
            [
                "python",
                "-c",
                "import torch; raise SystemExit(0 if 'sm_60' in "
                "torch.cuda.get_arch_list() else 1)",
            ],
            check=False,
        )
        if arch_check.returncode:
            subprocess.run(
                [
                    "python",
                    "-m",
                    "pip",
                    "install",
                    "-q",
                    "--index-url",
                    "https://download.pytorch.org/whl/cu121",
                    "torch==2.5.1",
                ],
                check=True,
            )
        from finetune.evaluate_v1_beta_checkpoints import run_evaluation

        summary = run_evaluation(
            "/kaggle/input",
            output,
            batch_size=64,
            forecast_batch_size=64,
            sample_count=3,
            seed=20260826,
        )
        required = (
            "summary.json",
            "evaluation_manifest.json",
            "experiment_manifest.json",
            "token_losses.csv.gz",
            "future_predictions.csv.gz",
            "run.log",
        )
        missing = [name for name in required if not (output / name).is_file()]
        if missing:
            raise RuntimeError(f"Evaluation output contract is incomplete: {missing}")
        (output / "status.json").write_text(
            json.dumps(
                {
                    "status": "complete",
                    "training_performed": False,
                    "primary_set": summary["interpretation"]["primary_set"],
                    "files": list(required),
                },
                indent=2,
            )
            + "\n"
        )
        print("Evaluation-only task completed; output contract verified", flush=True)
    except BaseException as exc:
        (output / "status.json").write_text(
            json.dumps(
                {
                    "status": "failed",
                    "error_type": type(exc).__name__,
                    "error": str(exc),
                },
                indent=2,
            )
            + "\n"
        )
        traceback.print_exc()
        raise


if __name__ == "__main__":
    main()
